mapper.select:
/*selectBuyerMpSoDlvryCmnPunchOutProgressList*/ SELECT B.PO_NO, B.PO_SEQ, B.LEGACY_PO_NO, B.LEGACY_PO_SEQ, B.REF_PR_NO, B.BUYER_ITEM_NO, B.DESCRIPTION, B.SPECIFICATION, B.UNIT_MEASURE, B.ITEM_QTY, B.UNIT_PRICE, B.ITEM_AMT, TO_DATE(C.DS_DATE,'YYYYMMDD') - TO_DATE(B.RD_DATE,'YYYYMMDD') DELAY_TIMES, B.DS_DELAY_REASON DELAY_REASON, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT) AGENT_NAME, A.PO_CREATE_DATE, B.RD_DATE, C.DS_DATE, D.ADD_USER_NAME, B.BUYER, D.CHANGE_USER_ID, B.DS_DELAY_REASON, A.AGENT, C.CD_QTY, (C.CD_QTY * B.UNIT_PRICE) AS CD_AMT , B.CONTRACT_NO, B.CONTRACT_SEQ FROM ICOMPOHD A , ICOMPODT B , ICOMPORS C , ICOMPRDT D WHERE A.BUYER = B.BUYER AND A.BUYER =#{st_com_code} AND B.RD_DATE BETWEEN TO_CHAR(SYSDATE , 'YYYYMMDD') and TO_CHAR(SYSDATE +5 , 'YYYYMMDD') AND A.PO_NO = B.PO_NO AND NVL(B.ITEM_QTY,0) <> NVL(B.GR_QTY,0) AND NVL(B.ITEM_QTY,0) <> NVL(B.DI_QTY,0) AND D.CHANGE_USER_ID = #{st_user_id}
AND B.LEGACY_PO_NO LIKE '%'||#{st_legacy_po_no}||'%'
AND B.BUYER_ITEM_NO LIKE '%'||#{st_buyer_item_no}||'%'
AND C.ADMIN_FLAG2 != 'Y' AND B.BUYER = C.BUYER AND B.PO_NO = C.PO_NO AND B.PO_SEQ = C.PO_SEQ AND B.BUYER = D.BUYER AND B.PR_NO = D.PR_NO AND B.PR_SEQ = D.PR_SEQ AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND D.STATUS <> 'D' ORDER BY B.LEGACY_PO_NO
